ACCEPTANCE=''
import base64,datetime,hashlib,json,subprocess
from pathlib import Path
A=json.loads(base64.b64decode(ACCEPTANCE))
U=A['unit'];I=A['invocation_id'];D=Path('/home/grinchenkoeg/computer-vision-homework-20261018/research_tmp/fg19_child_allthree_profile_v1')
def show(unit):
 keys=['InvocationID','LoadState','ActiveState','SubState','MainPID','ExecMainCode','ExecMainStatus','Result','ControlGroup']
 p=subprocess.run(['systemctl','--user','show','--all',unit,*sum((['-p',k]for k in keys),[])],capture_output=True,text=True,timeout=10)
 assert p.returncode==0,p.stderr
 return dict(line.split('=',1)for line in p.stdout.splitlines()if'='in line)
def population():
 p=show('wnn-campaign.slice');g=p['ControlGroup'];assert g not in ('','/')
 root=Path('/sys/fs/cgroup')/g.lstrip('/');paths=[root/'cgroup.procs',*root.rglob('cgroup.procs')];assert len(paths)<128
 return {str(q):v for q in paths if q.is_file()and(v:=q.read_text().strip())}
assert A['status']=='ACCEPTED'and(type(A['main_pid']),A['main_pid'],type(A['exec_main_code']),A['exec_main_code'],type(A['exec_main_status']),A['exec_main_status'])==(int,0,int,1,int,0)
for name,f in A['files'].items():
 p=D/name;assert p.is_file()and not p.is_symlink()and p.stat().st_size==f['bytes']<1000000
 assert hashlib.sha256(p.read_bytes()).hexdigest()==f['sha256']
for name,f in A['staged_code_pins'].items():
 p=D/name;assert p.is_file()and not p.is_symlink()and p.stat().st_size<1000000
 assert hashlib.sha256(p.read_bytes()).hexdigest()==f['sha256']
before=show(U);assert before['InvocationID']==I
assert tuple(before[k]for k in ('ActiveState','SubState','MainPID','ExecMainCode','ExecMainStatus','Result'))==('active','exited','0','1','0','success')
popbefore=population();assert popbefore=={}
s=subprocess.run(['systemctl','--user','stop',U],capture_output=True,text=True,timeout=20)
after=show(U);popafter=population()
assert s.returncode==0 and after['LoadState']=='not-found'and after['ActiveState']=='inactive'and after['SubState']=='dead'and after['MainPID']=='0'and after['InvocationID']==''and popafter=={}
print(json.dumps({'schema':'fg19-child-profile-exact-stop.v1','utc':datetime.datetime.now(datetime.UTC).isoformat(),'unit':U,'invocation_id':I,'acceptance_sha256':hashlib.sha256(base64.b64decode(ACCEPTANCE)).hexdigest(),'before':before,'stop':{'returncode':s.returncode,'stdout':s.stdout,'stderr':s.stderr},'after':after,'populated_before':popbefore,'populated_after':popafter,'scope':'Only accepted exited profile stopped; no healthy worker or failed support touched; no payload read/hash.'}))
